'use server'

import { createClient } from '@/utils/supabase/server'

export type BandMember = {
  id: string
  first_name: string
  last_name: string
  cadet_rank: string | null
  grade_level: string | null
  company: { company_name: string } | null
  extracurriculars: string[] | null
  email: string
}

export async function getBandRoster() {
  const supabase = createClient()
  
  const { data, error } = await supabase
    .from('profiles')
    .select(`
      id, 
      first_name, 
      last_name, 
      cadet_rank, 
      grade_level,
      extracurriculars,
      email,
      company:companies(company_name)
    `)
    .eq('is_in_band', true)
    .order('last_name', { ascending: true })

  if (error) {
    console.error('Error fetching band roster:', error)
    return []
  }

  // MANUAL MAPPING to fix Type Error
  // Supabase sometimes returns 'company' as an array if the relationship isn't 1-to-1 detected.
  // We force it into the shape we want.
  const members: BandMember[] = (data || []).map((m: any) => {
    // Handle case where company might be returned as an array or object
    const companyObj = Array.isArray(m.company) ? m.company[0] : m.company;

    return {
      id: m.id,
      first_name: m.first_name,
      last_name: m.last_name,
      cadet_rank: m.cadet_rank,
      grade_level: m.grade_level,
      email: m.email,
      // Ensure extracurriculars is treated as string[] or null
      extracurriculars: Array.isArray(m.extracurriculars) 
        ? m.extracurriculars 
        : (typeof m.extracurriculars === 'string' ? [m.extracurriculars] : null),
      company: companyObj ? { company_name: companyObj.company_name } : null
    }
  })

  return members
}